```go
// materialReconciliation 是一种物料在一个批次中的数量核对结果（千分之一克）：
// 应投量、累计实投量与差额（实投减应投）。
type materialReconciliation struct {
	materialNo string
	required   gramsMilli
	actual     gramsMilli
	difference gramsMilli
}

// reconcileBatchMaterials 是批次“逐物料数量核对”的唯一实现：给定批次记录 b
// 与其绑定的配方版本 r，按 r 的物料顺序逐项给出应投量（每份克数 × 计划份数，
// 由 planRequirements 计算）、累计实投量（仅累计该批次中该物料的投料，由
// feedingAccumulator 累计）与差额（实投减应投，可能为负，物料之间不互相
// 抵消）。每种物料恰有一项；没有投料的物料实投为零、差额为应投量的负值，
// 仍正常列出。
//
// 批次查询视图与已保存关闭结果的核对共用这里，保证两处对同一批次使用一致
// 的数量依据；创建、草稿调整与开始执行结果的“无投料”核对见
// validateUnfedRequirements。精度与上限规则不变：应投量逐物料以
// maxGramsMilli 为上限（由 planRequirements 判断），累计实投逐物料以
// maxGramsMilli 为上限（恰好达到合法），各种物料的数量不相加。
//
// 返回的错误不带错误分类，由调用方按各自场景包装（读取路径为
// ErrCorruptData 并补充批次编号等上下文）。
func reconcileBatchMaterials(b *batchRecord, r *recipeRecord) ([]materialReconciliation, error) {
	required, err := planRequirements(r, b.PlannedPortions)
	if err != nil {
		return nil, err
	}
	acc := newFeedingAccumulator()
	for _, f := range b.Feedings {
		if !acc.add(f.MaterialNo, f.GramsMilli) {
			return nil, fmt.Errorf("物料 %q 的累计实投超出上限 %s 克", f.MaterialNo, maxGramsMilli)
		}
	}
	out := make([]materialReconciliation, 0, len(required))
	for _, item := range required {
		actual := acc.total(item.materialNo)
		out = append(out, materialReconciliation{
			materialNo: item.materialNo,
			required:   item.requiredGrams,
			actual:     actual,
			difference: actual - item.requiredGrams,
		})
	}
	return out, nil
}
